const todos = $input.all().map((i) => i.json);
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const LINHA = '━━━━━━━━━━━━━━━━━━━━';
const MEDALHAS = ['🥇', '🥈', '🥉'];

const num = (v) => Number(v) || 0;
const fmtBRL = (v) => num(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const fmtPct = (v) => `${num(v).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%`;
const nome = (v) => {
  const p = String(v.nome_vendedor || '').trim().split(/\s+/)[0].toLowerCase();
  return p.charAt(0).toUpperCase() + p.slice(1);
};
const lista = (arr) => arr.map(nome).join(' • ');

// Só quem trabalhou no dia (venda, falta ou contato) entra nos rankings.
const ativos = todos.filter((v) => num(v.qtd_notas_dia) > 0 || v.lancou_falta || v.fez_contato);

if (ativos.length === 0) {
  return [{ json: { mensagem: `📊 *Performance do dia — ${hojeLabel}*\n\nNinguém registrou atividade hoje.` } }];
}

const linhas = [`📊 *Performance do dia — ${hojeLabel}*`, '', LINHA, '🎯 *META DO DIA*', ''];

// Meta diária: ranking por % atingido, medalha nos 3 primeiros
const comMetaDia = ativos
  .filter((v) => v.percentual_dia != null)
  .sort((a, b) => num(b.percentual_dia) - num(a.percentual_dia));
comMetaDia.forEach((v, idx) => {
  const pos = MEDALHAS[idx] ?? '▪️';
  linhas.push(`${pos} ${nome(v)} — ${fmtBRL(v.margem_dia)} de ${fmtBRL(v.meta_dia)} (${fmtPct(v.percentual_dia)})`);
});

// Meta semanal: realizado, % e faixa PROJETADA pelo ritmo (não a faixa bruta,
// que no começo da semana é sempre a mínima)
linhas.push('', LINHA, '📅 *META SEMANAL*', '');
const comMetaSemana = ativos
  .filter((v) => v.percentual_semana != null)
  .sort((a, b) => num(b.percentual_semana) - num(a.percentual_semana));
comMetaSemana.forEach((v) => {
  const faixa = v.faixa_semana_projetada != null ? Number(v.faixa_semana_projetada) : 3;
  linhas.push(`${nome(v)} — ${fmtBRL(v.margem_semana)} (${fmtPct(v.percentual_semana)}) · ritmo: *faixa ${faixa}%*`);
});
const totalSemana = todos.reduce((s, v) => s + num(v.margem_semana), 0);
linhas.push('', `💰 Margem da equipe na semana: *${fmtBRL(totalSemana)}*`);

// Clientes identificados nas vendas
linhas.push('', '👥 *CLIENTE IDENTIFICADO NAS VENDAS*');
const clientes = ativos
  .map((v) => {
    const total = num(v.vendas_cliente_real) + num(v.vendas_proprio_cpf) + num(v.vendas_sem_cliente);
    return { v, total, pct: total > 0 ? (num(v.vendas_cliente_real) / total) * 100 : null };
  })
  .filter((x) => x.total > 0)
  .sort((a, b) => b.pct - a.pct);
clientes.forEach(({ v, total, pct }) => {
  const alerta = pct < 50 ? ' ⚠️' : '';
  linhas.push(`${nome(v)} — ${num(v.vendas_cliente_real)}/${total} → ${Math.round(pct)}%${alerta}`);
});

// Ações do dia: só destaca quem fez
linhas.push('', LINHA, '⚙️ *AÇÕES DO DIA*', '');
const fizeramContato = ativos.filter((v) => v.fez_contato);
const lancaramFalta = ativos.filter((v) => v.lancou_falta);
linhas.push(fizeramContato.length ? `📞 Contatos realizados: ✅ ${lista(fizeramContato)}` : '📞 Contatos realizados: ninguém hoje');
linhas.push(lancaramFalta.length ? `📦 Faltas lançadas: ✅ ${lista(lancaramFalta)}` : '📦 Faltas lançadas: ninguém hoje');

// Foco de amanhã: só entra o que aconteceu de verdade hoje
const foco = [];
const bateram = comMetaDia.filter((v) => num(v.percentual_dia) >= 100);
if (bateram.length) foco.push(`🏆 Bateram a meta do dia: ${lista(bateram)}. Parabéns!`);
const abaixo = comMetaDia.filter((v) => num(v.percentual_dia) < 100);
if (abaixo.length) foco.push(`💰 Recuperar o ritmo: ${abaixo.map((v) => `${nome(v)} (${fmtPct(v.percentual_dia)})`).join(' • ')}`);
const semIdent = clientes.filter((x) => x.pct < 50);
if (semIdent.length) foco.push(`🪪 Identificar o cliente na venda: ${semIdent.map((x) => `${nome(x.v)} (${Math.round(x.pct)}%)`).join(' • ')}`);
if (!fizeramContato.length) foco.push('📞 Ninguém fez contato ativo hoje — vamos ligar pra pelo menos 1 cliente cada.');
if (!lancaramFalta.length) foco.push('📦 Ninguém lançou produto em falta hoje — o que faltou no balcão?');

if (foco.length) {
  linhas.push('', LINHA, '🎯 *FOCO DE AMANHÃ*', '', ...foco);
}

return [{ json: { mensagem: linhas.join('\n').trim() } }];

// Só chega aqui quem ficou 2 dias seguidos (hoje E ontem) com margem
// abaixo da meta do dia — não distingue "folga/dia livre" de
// "desempenho fraco" (não checa atividade, diferente da mensagem de
// recap) — é uma primeira versão, calibrar depois se der falso positivo.
const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

const blocos = linhas.map(
  (v) =>
    `⚠️ *${v.nome_vendedor}*\nHoje: ${fmtBRL(v.margem_hoje)} · Ontem: ${fmtBRL(v.margem_ontem)} (meta do dia: ${fmtBRL(v.meta_dia)})`
);

const mensagem = `📉 *2 dias seguidos abaixo da meta — ${hojeLabel}*\n\n${blocos.join('\n\n')}`;

return [{ json: { mensagem } }];
